Use Flask-Login for session management and Argon2 for password hashing. Store only hashed passwords in SQLite through Flask-SQLAlchemy.

```bash
pip install Flask-Login Flask-Argon2 Flask-SQLAlchemy
```

```python
# auth.py
from flask import Blueprint, render_template, request, redirect, url_for, flash
from flask_login import login_user, logout_user
from flask_argon2 import Argon2

from models import User

auth = Blueprint("auth", __name__)
argon2 = Argon2()


def hash_password(password: str) -> str:
    return argon2.generate_password_hash(password)


def validate_login(password: str, stored_hash: str) -> bool:
    return argon2.check_password_hash(stored_hash, password)


@auth.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form["username"]
        password = request.form["password"]

        user = User.query.filter_by(username=username).first()

        if user and validate_login(password, user.password_hash):
            login_user(user)
            return redirect(url_for("dashboard"))

        flash("Invalid username or password.", "error")

    return render_template("login.html")


@auth.route("/logout")
def logout():
    logout_user()
    return redirect(url_for("auth.login"))
```

