Yes. Keep it dependency-free with a small `localStorage` cache: store the last 3 city responses with timestamps, then reuse entries until they expire.

```js
const CACHE_KEY = 'weather-cache';
const MAX_CITIES = 3;
const TTL = 5 * 60 * 1000; // 5 minutes

function readCache() {
  return JSON.parse(localStorage.getItem(CACHE_KEY) || '{}');
}

function writeCache(cache) {
  localStorage.setItem(CACHE_KEY, JSON.stringify(cache));
}

async function fetchWeather(city) {
  const cache = readCache();
  const key = city.trim().toLowerCase();
  const cached = cache[key];

  if (cached && Date.now() - cached.timestamp < TTL) {
    return cached.data;
  }

  const response = await fetch(`/api/weather?city=${encodeURIComponent(city)}`);

  if (!response.ok) {
    throw new Error(`Weather request failed: ${response.status}`);
  }

  const data = await response.json();

  cache[key] = { data, timestamp: Date.now() };

  // Keep only the 3 most recently stored cities.
  const keys = Object.keys(cache);
  while (keys.length > MAX_CITIES) {
    delete cache[keys.shift()];
  }

  writeCache(cache);
  return data;
}
```

This matches your existing lightweight approach: vanilla JavaScript, timestamped `localStorage`, and a maximum of three cached cities. For autocomplete, use a separate in-memory cache with up to 100 entries and a 5-minute expiration.
